WITH top_return_customers AS (SELECT cr.cr_returning_customer_sk, SUM(cr.cr_net_loss) AS total_net_loss, ROW_NUMBER() OVER (ORDER BY SUM(cr.cr_net_loss) DESC) AS rn FROM catalog_returns cr GROUP BY cr.cr_returning_customer_sk HAVING SUM(cr.cr_net_loss) > 0), customer_sales AS (SELECT ws.ws_bill_customer_sk, SUM(ws.ws_ext_sales_price) AS total_sales_amount FROM web_sales ws GROUP BY ws.ws_bill_customer_sk), customer_top_reason AS (SELECT cr.cr_returning_customer_sk, r.r_reason_desc, ROW_NUMBER() OVER (PARTITION BY cr.cr_returning_customer_sk ORDER BY COUNT(*) DESC) AS rn_reason FROM catalog_returns cr JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk GROUP BY cr.cr_returning_customer_sk, r.r_reason_desc) SELECT trc.cr_returning_customer_sk, trc.total_net_loss, COALESCE(cs.total_sales_amount, 0) AS total_sales_amount, CASE WHEN COALESCE(cs.total_sales_amount, 0) = 0 THEN 0 ELSE trc.total_net_loss / cs.total_sales_amount END AS loss_to_sales_ratio, CASE WHEN (trc.total_net_loss / NULLIF(cs.total_sales_amount, 0)) > 0.20 THEN 'High Risk' ELSE 'Normal' END AS risk_flag, ctr.r_reason_desc AS most_common_return_reason, LAG(trc.total_net_loss) OVER (ORDER BY trc.total_net_loss DESC) AS previous_customer_loss, LEAD(trc.total_net_loss) OVER (ORDER BY trc.total_net_loss DESC) AS next_customer_loss FROM top_return_customers trc LEFT JOIN customer_sales cs ON trc.cr_returning_customer_sk = cs.ws_bill_customer_sk LEFT JOIN customer_top_reason ctr ON trc.cr_returning_customer_sk = ctr.cr_returning_customer_sk AND ctr.rn_reason = 1 WHERE trc.rn <= 10 ORDER BY trc.total_net_loss DESC
